/// Apply download configuration without downloading anything.
///
/// Use this to set a custom cache directory before the first call to
/// `get_language` or any download function. Changing the cache dir
/// after languages have been registered has no effect on already-loaded
/// languages.
///
/// `PackConfig::cache_dir` is a BASE directory, not the final libs path: this
/// crate appends `tree-sitter-language-pack/v{version}/libs` to it, the same
/// suffix applied to the platform default cache directory. In the example below,
/// files actually land under `/tmp/my-parsers/tree-sitter-language-pack/v{version}/libs/`,
/// never directly in `/tmp/my-parsers/`. Call `cache_dir` to read back the
/// resolved, fully-suffixed path.
/// \note Returns an error if the lock cannot be acquired.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
/// \code
/// use std::path::PathBuf;
/// use tree_sitter_language_pack::{PackConfig, configure};
///
/// let config = PackConfig {
///     cache_dir: Some(PathBuf::from("/tmp/my-parsers")),
///     languages: None,
///     groups: None,
/// };
/// configure(&config).unwrap();
/// \endcode
#[cfg(feature = "download")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_pack_configure(config: AlefHandle) -> i32 {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = [Some(HandleRequest {
            handle: config,
            expected_type: std::any::TypeId::of::<tree_sitter_language_pack::PackConfig>(),
        })]
        .into_iter()
        .flatten()
        .collect();
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return -1;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return -1;
                }
            }
        }
        if config == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'config'",
            );
            return -1;
        }
        let config_rs_ptr = match locked_handle_ptr::<tree_sitter_language_pack::PackConfig>(&mut __alef_guards, config)
        {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return -1;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let config_rs = unsafe { &*config_rs_ptr };

        let result = tree_sitter_language_pack::configure(&config_rs);
        match result {
            Ok(()) => 0,
            Err(e) => {
                set_last_error(alef_ffi_error_code(&e), &e.to_string());
                -1
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            -1
        }
    }
}

