/// freed with the appropriate free function.
/// \code
/// use tree_sitter_language_pack::{ProcessConfig, process};
///
/// let config = ProcessConfig::new("python").all();
/// let result = process("def hello(): pass", &config).unwrap();
/// println!("Language: {}", result.language);
/// println!("Lines: {}", result.metrics.total_lines);
/// println!("Structures: {}", result.structure.len());
/// \endcode
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_pack_process(source: *const std::ffi::c_char, config: AlefHandle) -> AlefHandle {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = [Some(HandleRequest {
            handle: config,
            expected_type: std::any::TypeId::of::<tree_sitter_language_pack::ProcessConfig>(),
        })]
        .into_iter()
        .flatten()
        .collect();
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return 0;
                }
            }
        }
        if source.is_null() {
            set_last_error(1, "Null pointer passed for parameter 'source'");
            return 0;
        }
        // SAFETY: null check above guarantees source is a valid pointer; string is valid UTF-8 from caller.
        let source_rs = match unsafe { CStr::from_ptr(source) }.to_str() {
            Ok(s) => s.to_string(),
            Err(_) => {
                set_last_error(1, "Invalid UTF-8 in parameter 'source'");
                return 0;
            }
        };

        if config == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'config'",
            );
            return 0;
        }
        let config_rs_ptr =
            match locked_handle_ptr::<tree_sitter_language_pack::ProcessConfig>(&mut __alef_guards, config) {
                Ok(value) => value,
                Err(error) => {
                    set_handle_error(&error);
                    return 0;
                }
            };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let config_rs = unsafe { &*config_rs_ptr };

        let result = tree_sitter_language_pack::process(&source_rs, &config_rs);
        match result {
            Ok(val) => match insert_handle(val) {
                Ok(handle) => handle,
                Err(error) => {
                    set_handle_error(&error);
                    0
                }
            },
            Err(e) => {
                set_last_error(alef_ffi_error_code(&e), &e.to_string());
                0
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            0
        }
    }
}
